  await expect(tab(page, 'Sheet1')).toHaveAttribute('aria-selected', 'true');
  await expectCellText(page, 'A1', 'Alpha');
  await expect(formulaBar(page)).toHaveValue('Alpha');

  await page.reload();
  await expect(tab(page, 'Sheet1')).toHaveAttribute('aria-selected', 'true');
  await expectCellText(page, 'A1', 'Alpha');
  await expect(formulaBar(page)).toHaveValue('Alpha');
});

